A=/home/runner/czaba-project/tmp/studio-real-loop/a-round-468; mkdir -p $A/proposal-visual; cat > $A/visual.cjs <<'EOF'
const { chromium } = require('/home/runner/czaba-project/store/node_modules/playwright');
const fs=require('fs');const out=process.argv[2];
(async()=>{const b=await chromium.launch();const res=[];
for(const vp of [{width:1440,height:900},{width:1280,height:720}])for(const [tag,port] of [['before',3468],['after',3469]]){
 const ctx=await b.newContext({viewport:vp});await ctx.addInitScript(()=>{localStorage.setItem('czaba_lead_magnet',JSON.stringify({viewCount:99,lastShown:Date.now(),dismissed:true,submitted:true}));});
 const p=await ctx.newPage();await p.goto(`http://127.0.0.1:${port}/`,{waitUntil:'load'});await p.waitForTimeout(3000);
 const secs=await p.evaluate(()=>[...document.querySelectorAll('.homepage > div')].slice(0,2).map(d=>{const r=d.getBoundingClientRect();return {top:Math.round(r.top+scrollY),h:Math.round(r.height)}}));
 for(const [i,name] of [[0,'product-section'],[1,'studio-showcase']]){const s=secs[i];
  await p.evaluate(y=>window.scrollTo(0,y),s.top-100);await p.waitForTimeout(2500);
  await p.addStyleTag({content:'header{visibility:hidden!important}'});
  const el=(await p.$$('.homepage > div'))[i];const f=`${out}/${name}-${vp.width}-${tag}.png`;await el.screenshot({path:f,animations:'disabled'});res.push(f);}
 await ctx.close();}
// diff in browser canvas
const ctx=await b.newContext();const p=await ctx.newPage();
const pairs=[];for(const vp of [1440,1280])for(const n of ['product-section','studio-showcase'])pairs.push([n,vp]);
const stats=[];for(const [n,vp] of pairs){const a=fs.readFileSync(`${out}/${n}-${vp}-before.png`).toString('base64');const c=fs.readFileSync(`${out}/${n}-${vp}-after.png`).toString('base64');
 const r=await p.evaluate(async([a,c])=>{const load=s=>new Promise(r=>{const i=new Image();i.onload=()=>r(i);i.src='data:image/png;base64,'+s});const [ia,ic]=await Promise.all([load(a),load(c)]);const w=Math.min(ia.width,ic.width),h=Math.min(ia.height,ic.height);
  const g=img=>{const cv=document.createElement('canvas');cv.width=w;cv.height=h;const x=cv.getContext('2d');x.drawImage(img,0,0);return x.getImageData(0,0,w,h).data};const da=g(ia),dc=g(ic);let sum=0,max=0,n10=0,lumA=0,lumC=0;
  for(let i=0;i<da.length;i+=4){const d=(Math.abs(da[i]-dc[i])+Math.abs(da[i+1]-dc[i+1])+Math.abs(da[i+2]-dc[i+2]))/3;sum+=d;if(d>max)max=d;if(d>10)n10++;lumA+=da[i]+da[i+1]+da[i+2];lumC+=dc[i]+dc[i+1]+dc[i+2];}
  const N=da.length/4;return {w,h,sizeA:[ia.width,ia.height],sizeC:[ic.width,ic.height],meanAbsDiff:+(sum/N).toFixed(3),maxDiff:+max.toFixed(1),pctOver10:+(100*n10/N).toFixed(3),meanLumBefore:+(lumA/N/3).toFixed(2),meanLumAfter:+(lumC/N/3).toFixed(2)}},[a,c]);
 stats.push({section:n,vp,...r});}
fs.writeFileSync(`${out}/diff-stats.json`,JSON.stringify(stats,null,1));console.log(JSON.stringify(stats,null,1));await b.close();})();
EOF
cd $A && node visual.cjs $A/proposal-visual
